function generateShade(baseColor, i, lightDown) {
  const baseHue = baseColor.h;
  const baseSaturation = baseColor.s;
  let lightStep = 50 / setWaves;
  let baseLightness;
  if (lightDown == 1) {
    baseLightness = 15 + (i * lightStep);
  } else {
      baseLightness = 65 - (i * lightStep);
    }
  return { h: baseHue, s: baseSaturation, l: baseLightness};
}

function setPointRange(setPoints, i) {
  let pointGap = canvw / setPoints;
  let pty;
  hashFlip = R.random_int(0,1); // decides if the wave goes up or down
  if (R.random_bool(.5) == true && i > 1 && setPoints <= 5) {
    setY = R.random_num(.01, .05);
  } else {
      setY = R.random_num(.006, .02);
      }
  points = [];
  points.push([canvw * -.01, startY]);
  points.push([canvw * -.01, startY]);
  for (let i = 0; i < setPoints; i++) {
    let ptx = (i + 1) * pointGap;
    if ((hashFlip + i) % 2 === 0) {
      pty = startY + (canvw * setY);
    } else {
      pty = startY - (canvw * setY);
      }
    points.push([ptx, pty]);
  }
  points.push([canvw * 1.01, startY]);
  points.push([canvw * 1.01, startY]);
}

function Paper() {
