    stroke (R.random_int(1, 360), 50, R.random_int(30,60), R.random_num(1, 1));
    x = R.random_num((-canvw * 0.2), (canvw * 1.2));
    y = R.random_num((-canvh * 0.2), (canvh * 1.2));
    push();
    translate(x,y);
    strokeWeight(canvw / 1000);
    rotate(R.random_num(0, PI*2));
    curve(R.random_num((canvw / 8.33), (canvw / 2.25)), (canvw / 500), (canvw / 500), R.random_num((canvw / -10), (canvw / 10)), R.random_num((canvw / -10), (canvw / 10)), R.random_num((canvw / 8.33), (canvw / 4)), R.random_num((canvw / 8.33), (canvw / 4)), R.random_num((canvw / 8.33), (canvw / 2.25)));
    pop();
  }
}
